import localFont from "next/font/local";
import "../styles/global.scss"

const panton = localFont({
  src: [
    { path: "../public/fonts/panton-thin.otf", weight: "100", style: "normal" },
    { path: "../public/fonts/panton-light.otf", weight: "300", style: "normal" },
    { path: "../public/fonts/panton-regular.otf", weight: "400", style: "normal" },
    { path: "../public/fonts/panton-semi-bold.otf", weight: "600", style: "normal" },
    { path: "../public/fonts/panton-bold.otf", weight: "700", style: "normal" },
    { path: "../public/fonts/panton-black.otf", weight: "800", style: "normal" },
    { path: "../public/fonts/panton-extra-black.otf", weight: "900", style: "normal" },
  ],
  variable: "--font-panton",
  display: "swap",
})

const nexaRust = localFont({
  src: [{ path: "../public/fonts/NexaRustSansBlack2.ttf", weight: "400", style: "normal" }],
  variable: "--font-nexa-rust",
  display: "swap",
})

export const metadata = {
  title: "Rocksport In-school Program",
  description: "Adventure programs for schools by Rocksport",
};

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <body className={`${panton.variable} ${nexaRust.variable} antialiased`}>
        {children}
      </body>
    </html>
  );
}
